"use strict";

var child_process = require("child_process");

var path = require("path");

var fs = require("fs");

var commander = require("commander");

const VERSION = "0.0.0-9";

const esrunPath = path.join(__dirname, "../node_modules/.bin/esrun");

const fileExtensions = [ ".ts", ".js" ];

const runnerExtensions = [ ".runner", ".run", ".test" ];

const SILENT_PASS = process.env.RUNNER_SILENT_PASS === "true";

const MAGENTA_BACKGROUND = "\u001b[45m%s\u001b[0m";

const RED_BACKGROUND = "\u001b[41m%s\u001b[0m";

const isRunnerFile = value => {
    const extension = path.extname(value);
    if (!fileExtensions.includes(extension)) {
        return false;
    }
    for (const runnerExtension of runnerExtensions) {
        const combinedExtension = runnerExtension + extension;
        const runnerRegExp = new RegExp(`${combinedExtension}$`);
        if (value.match(runnerRegExp)) {
            return true;
        }
    }
    return false;
};

async function* getFiles(dir) {
    const dirents = await fs.promises.readdir(dir, { withFileTypes: true });
    for (const dirent of dirents) {
        const res = path.resolve(dir, dirent.name);
        if (dirent.isDirectory()) {
            yield* getFiles(res);
        } else {
            yield res;
        }
    }
}

class Collector {
    constructor(runnersPath) {
        const pathValue = path.isAbsolute(runnersPath) ? runnersPath : path.join(process.cwd(), runnersPath);
        this.runnersPath = pathValue;
    }
    async collect() {
        const runnersStats = fs.statSync(this.runnersPath);
        if (runnersStats.isFile()) {
            if (isRunnerFile(this.runnersPath)) {
                return [ this.runnersPath ];
            }
            return [];
        }
        const runnerFiles = [];
        for await (const file of getFiles(this.runnersPath)) {
            if (isRunnerFile(file)) {
                runnerFiles.push(file);
            }
        }
        return runnerFiles;
    }
}

const collectAndRun = async (runPath) => {
    try {
        const collector = new Collector(runPath || process.cwd());
        const runners = await collector.collect();
        for (const runner of runners) {
            try {
                if (runner.endsWith(".ts")) {
                    const esrun = child_process.exec(`${esrunPath} ${runner}`);
                    esrun.stdout?.on("data", (data) => {
                        console.log(data);
                    });
                    esrun.stderr?.on("data", (data) => {
                        console.log(data);
                    });
                } else {
                    require(runner);
                }
            } catch (error) {
                console.log(`\n\tcould not evaluate run in '${runner}'\n`, error);
                continue;
            }
        }
        return;
    } catch (error) {
        console.log(`\n\tcould not read runs in '${runPath}'\n`, error);
        return;
    }
};

const run = async (runPaths) => {
    if (runPaths.length === 0) {
        collectAndRun();
        return;
    }
    for (const runPath of runPaths) {
        collectAndRun(runPath);
    }
};

const main = async (program) => {
    program.storeOptionsAsProperties(true);
    program.name("runner").usage("[...path]").version(VERSION, "-v, --version").action(async (_, options) => {
        await run(options.args || []);
    });
    program.parseAsync(process.argv);
};

const cli = () => {
    main(commander.program);
};

const command = async (cmd, args) => {
    try {
        const commandText = [ cmd, ...args ].join(" ");
        const result = child_process.execSync(commandText).toString();
        try {
            return JSON.parse(result);
        } catch (error) {
            return result;
        }
    } catch (error) {
        console.log("curl error", error);
        return;
    }
};

const curl = async (args) => {
    return command("curl", args);
};

const runner = async (prepareOrRun, run, postpare, options) => {
    try {
        let checks = [];
        const check = mode => (message = "", testValue, expectedValue, relationship = "==") => {
            let passed = false;
            switch (relationship) {
              case "==":
                if (testValue === expectedValue) {
                    passed = true;
                }
                break;
              case "<":
                if (testValue < expectedValue) {
                    passed = true;
                }
                break;
              case "<=":
                if (testValue <= expectedValue) {
                    passed = true;
                }
                break;
              case ">":
                if (testValue > expectedValue) {
                    passed = true;
                }
                break;
              case ">=":
                if (testValue >= expectedValue) {
                    passed = true;
                }
                break;
              default:
                break;
            }
            checks.push({
                testValue: testValue,
                expectedValue: expectedValue,
                relationship: relationship,
                passed: passed,
                message: message,
                mode: mode
            });
            return passed;
        };
        if (!run) {
            const run = prepareOrRun;
            await run(check("run"));
        } else {
            const prepare = prepareOrRun;
            const prepared = await prepare(check("prepare"));
            const runned = await run(check("run"), prepared);
            if (postpare) {
                await postpare(check("postpare"), prepared, runned);
            }
        }
        for (const check of checks) {
            const {testValue, expectedValue, relationship, passed, message, mode} = check;
            if (((options?.silentPass) || SILENT_PASS) && passed) {
                return;
            }
            const passedString = passed ? "passed" : "failed";
            const notString = passed ? "" : "not ";
            const testValueString = typeof testValue === "string" ? `'${testValue}'` : testValue.toString();
            const expectedValueString = typeof expectedValue === "string" ? `'${expectedValue}'` : expectedValue.toString();
            const messageString = message ? `:: ${message.toString()} ` : "";
            const colors = passed ? MAGENTA_BACKGROUND : RED_BACKGROUND;
            const modeString = `${mode} ${passedString}`;
            const logString = `${messageString}:: ${testValueString} ${notString}${relationship} ${expectedValueString}`;
            console.log(colors, modeString, logString);
        }
    } catch (error) {
        console.log("run error", error);
        return;
    }
};

exports.cli = cli;
exports.command = command;
exports.commands = { run };
exports.curl = curl;
exports["default"] = runner;

